"""Build seven fixed-window Ukraine chapters. Offline, original cited annotations.

Reuse the licensed UCDP and UNHCR series already built by Orbis; run
ukraine_lights.py separately to reproduce NASA display images. No fronts are inferred.
"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'data/history/ukraine'
OUT.mkdir(parents=True,exist_ok=True)
UN14='https://press.un.org/en/2014/ga11493.doc.htm'
UN22='https://press.un.org/en/2022/ga12407.doc.htm'
OCC='https://ukraine.un.org/sites/default/files/2024-04/2024-03-20-OHCHR-Report-Occupation-Aftermath-en.pdf'
DET='https://ukraine.ohchr.org/en/arbitrary-detention-torture-and-ill-treatment-context-armed-conflict-EN'
NORTH='https://ukraine.un.org/en/210464-un-report-details-summary-executions-and-attacks-individual-civilians-russian-troops'
KHR='https://ukraine.un.org/en/207300-ukraine-humanitarians-bring-water-food-medicines-and-other-essential-supplies-thousands'
DAM='https://ukraine.un.org/en/235545-potential-long-term-impact-destruction-kakhovka-dam'
NASA='https://science.nasa.gov/earth/earth-observatory/tracking-night-lights-in-ukraine-150002/'
REF='https://www.unhcr.org/sites/default/files/2026-01/unhcr-2025-emergencies-and-protracted-crises-impact-report.pdf'
KY=[30.52,50.45]; KH=[36.23,49.99]; HE=[32.62,46.64]
def write(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def event(title,date,at,text,url,kind):return dict(title=title,date=date,at=at,text=text,url=url,source=url,kind=kind)
def card(title,text,kind,center=[33,49],zoom=5):
 return dict(title=title,text=text,view=dict(mode='globe',center=center,zoom=zoom),layers=[dict(type='cards',data='notes',kinds=[kind],list=True)],sources=['editorial'])
def events(title,text,years,center=[34,49],zoom=5,start=None):
 return dict(title=title,text=text,view=dict(mode='globe',center=center,zoom=zoom),timeline=dict(years=years,start=start or years[0],format='month'),layers=[dict(type='events',data='violence',year='t',window=1,color='muted',minR=1.5,maxR=10,vmax=150,title='UCDP deadly events / cell / month')],sources=['ucdp-ged'])
def story(id,title,hook,items,scenes,sources=None,data=None,notes=''):
 kinds={e['kind']:dict(label=e['kind'].replace('_',' ').title(),color='muted') for e in items}
 write(OUT/(id+'.json'),dict(source='editorial',asOf='Fixed historical references; editorial cutoff 2026-10-14',retrieved='2026-10-14',units='Selected factual annotations, no exhaustive event count',note='Original paraphrases with primary citations. Coordinates approximate named city/region anchors, not footprints. A date may mark a reporting cutoff rather than the onset of an event; the card says which.',kinds=kinds,items=items))
 d=dict(notes='data/history/ukraine/'+id+'.json',violence='data/events/conflict-ukraine.json');d.update(data or {})
 write(ROOT/'stories'/(id+'.json'),dict(id=id,cat='Geopolitics',title=title,hook=hook,updated='2026-10-14',sources=['editorial']+(sources or []),data=d,notes='Fixed editorial cutoff: 14 October 2026. This is not a live map. The modern Natural Earth basemap provides orientation; its border conventions do not establish legal recognition, sovereignty or military control. Cards are selected approximate locators. UCDP events are incidents of organized violence with at least one death, aggregated into 0.25-degree cells by start month. Event locations are coded approximations; country-only/unlocated records are omitted. Only records assigned to Ukraine are shown, excluding Russia. GED 26.1 covers through December 2025; Candidate 26.0.8 extends through August 2026 and is preliminary. Circles measure events, not territory, troop strength or civilian deaths. '+notes,scenes=scenes))

items=[event('Crimea referendum',20140316,[34.1,44.95],'The UN General Assembly declared the 16 March referendum invalid in its 27 March resolution, reaffirming Ukraine’s internationally recognized territorial integrity.',UN14,'crimea'),event('Donetsk',20140414,[37.8,48.02],'OHCHR’s eastern-Ukraine detention study begins on 14 April 2014 and covers Government actors and armed groups in Donetsk and Luhansk areas. This is the study window, not a claimed start date for every incident.',DET,'donbas'),event('Luhansk',20140414,[39.3,48.57],'The same OHCHR report addresses arbitrary detention and ill-treatment by multiple actors through April 2021.',DET,'donbas'),event('Eight years before the invasion',20211231,[37.8,48.02],'OHCHR describes hostilities over control in eastern Ukraine during the eight years preceding the full-scale attack. This year-end locator summarizes the period rather than a new battle.',OCC,'continuity'),event('Human rights across the divide',20210430,[36.23,49.99],'OHCHR’s study includes case studies of detention by the Security Service of Ukraine in Kharkiv and an armed-group detention facility in Donetsk. Protection obligations apply to every actor.',DET,'rights')]
story('ua-2014','Crimea and Donbas','The war’s earlier geography and the people living across contested lines.',items,[card('Crimea, March 2014','A referendum under Russian occupation did not change the UN’s recognition of Ukraine’s territorial integrity. The point locates Crimea; it does not shade annexation as lawful sovereignty.','crimea',[34,45],6),card('Conflict in the east','Donetsk and Luhansk became central to an armed conflict that preceded February 2022. These regional anchors locate the places addressed by OHCHR; they do not draw the changing line of contact.','donbas',[38,49],6),card('A war before the full-scale war','OHCHR’s historical context records eight years of hostilities before the 2022 attack. A chapter beginning in 2022 alone would leave this history out.','continuity',[37,49],5.5),card('Rights did not stop at a line','OHCHR documented arbitrary detention and ill-treatment involving Government actors and armed groups. Its 2014–2021 study examines accountability as well as abuse; a map of military geography cannot tell that whole story.','rights',[37,49],5.5)],notes='2014 legal context: '+UN14+' . Detention study: '+DET+' . Historical context: '+OCC+' paragraphs 29–32.')

items=[event('Full-scale attack',20220224,KY,'Russia launched its full-scale armed attack on 24 February 2022. The Kyiv marker anchors the national event, not its only direction.',OCC,'attack'),event('Mariupol siege',20220531,[37.55,47.1],'OHCHR describes Mariupol as under siege for nearly three months, with intensive bombardment. May marks the end of this reporting interval, not an exact surrender date.',OCC,'siege'),event('General Assembly response',20220302,[-73.97,40.75],'On 2 March the General Assembly demanded Russia end the invasion and withdraw its military forces.',UN22,'response')]
story('ua-invasion','The invasion','February 2022 opened a much wider war.',items,[card('24 February 2022','Russia’s full-scale attack widened the war across multiple fronts. Kyiv is an orientation point here; the next scene uses independently coded deadly incidents rather than invented arrows or occupied polygons.','attack'),events('The first months in the record','Move from February to March and April 2022. Each circle counts deadly events assigned to a cell in that month. February begins with a partial invasion month; coded locations are sometimes approximate.',[202202,202203,202204]),card('Mariupol','A prolonged siege and intensive bombardment struck Mariupol. The locator marks the city discussed by OHCHR. It gives neither a casualty total nor a measured footprint of destruction.','siege',[37.55,47.1],7),card('An international response','The UN General Assembly demanded an end to the invasion and withdrawal on 2 March 2022. The New York locator connects the military geography to the institution responding to it.','response',[-73.97,40.75],3)],['ucdp-ged'],notes='OHCHR context '+OCC+' paragraphs 31–32; UN resolution coverage '+UN22+' .')

items=[event('Northern withdrawal',20220331,KY,'OHCHR records Russian withdrawal from the northern front by the end of March. This month-end marker is not an exact day for every settlement.',OCC,'north'),event('Kharkiv region regained',20221130,[37.25,49.19],'By the end of November 2022, OHCHR reports Ukraine had regained nearly all Kharkiv region. The point locates Izium within the region, not all territory recovered or a precise September handover.',OCC,'east'),event('Kherson city',20221111,HE,'Ukraine regained Kherson city on 11 November. A UN convoy arrived on 14 November, less than 72 hours afterward.',KHR,'south'),event('Recovery work',20231231,HE,'OHCHR describes restoration of services and mine clearance in formerly occupied areas through 2023. Control changing hands did not remove civilian needs.',OCC,'aftermath')]
story('ua-counteroffensives','Kyiv, Kharkiv and Kherson','Different turning points in 2022, with an aftermath that outlasted them.',items,[card('The northern front receded','By the end of March 2022, Russian forces withdrew from the northern front. This turning point is located near Kyiv; a point cannot reconstruct the changing extent of control.','north',[30.5,50.5],6),card('The Kharkiv region changed','The 2022 counteroffensives returned nearly all Kharkiv region to Ukrainian control by November, according to OHCHR. Izium provides a regional anchor. This scene deliberately gives the report’s end-November assessment rather than a fabricated daily front.','east',[37,49.3],6),card('Kherson, 11 November','Ukraine regained Kherson city in November. The UN’s first convoy arrived within days. The city’s recovery is distinct from the whole region: OHCHR describes recovered areas on the Dnipro’s right bank.','south',HE,6.5),card('After control changed','Returning public services, clearing mines and repairing homes were part of the aftermath. OHCHR’s account extends through December 2023; its reporting date should not be read as a current map of safety.','aftermath',HE,6)],notes='Control claims use '+OCC+' paragraphs 31–32 and 163, plus the dated UN convoy account '+KHR+' . No daily control polygons or reclaimed-area measurements are supplied.')

items=[event('Kakhovka dam destruction',20230606,[33.37,46.77],'The destruction of the Kakhovka dam on 6 June 2023 flooded downstream communities and disrupted upstream water access. This locator is not a flood extent.',DAM,'water')]
story('ua-front','The long front','A monthly event record follows an extended war without pretending to draw its front.',items,[events('A record that keeps going','The UCDP record extends beyond the 2022 turning points. Compare selected months from 2023 through 2025. The fixed circle scale counts deadly events; it cannot show which side controlled the ground.',[202301,202306,202312,202406,202412,202506,202512],[36,48.5],6),events('The east in detail','Zoom into eastern Ukraine and compare the same dated event cells. Multiple incidents can share a city or province anchor. Apparent concentration partly reflects coding and reporting, so these are not surveyed battlefield coordinates.',[202306,202406,202506,202512],[37,49],6.5),card('War reaches water systems','The Kakhovka dam’s destruction in June 2023 affected communities on both sides of the river and people dependent on its reservoir. The site marker cannot substitute for a verified flood map.','water',[33,47],6),events('What an empty cell means','No circle means no included record in that cell and month. It does not prove peace, civilian safety or one side’s control. Candidate months in 2026 are preliminary and can be revised.',[202601,202604,202608],[35,49],5)],['ucdp-ged'],notes='Kakhovka consequences '+DAM+' . UCDP window and country inclusion are preserved from the existing data build.')

def image(month):return dict(type='image',src='data/history/ukraine/kyiv-lights-'+month+'.webp',alt='NASA night-light display composite around Kyiv, '+month[:4]+'-'+month[4:],caption='Kyiv region • '+month[:4]+'-'+month[4:]+' • display imagery',credit='NASA Earth Observatory / Joshua Stevens; Black Marble: Ranjay Shrestha / NASA GSFC',licence='NASA public-use imagery with credit',href=NASA)
items=[event('NASA comparison (published)',20220630,KY,'NASA published January, March and May 2022 composites around Kyiv. Selected cloud-free nights and Landsat context support the display comparison.',NASA,'lights'),event('A hydropower system disrupted',20230606,[33.37,46.77],'Kakhovka’s destruction affected water supply as well as the hydropower facility. The UN assessment distinguishes downstream flooding and upstream loss of water.',DAM,'dam')]
s=[]
for title,text,month in [('January: a baseline','January 2022 is the pre-invasion baseline in NASA’s Kyiv comparison. The inset is a display composite, with nighttime lights over Landsat context. It is not georeferenced onto the map.','202201'),('March: reduced lighting','NASA’s March composite shows reduced lighting around Kyiv. A darker display cannot distinguish damaged supply, deliberate dimming and changes in activity on its own.','202203'),('May: some light returns','NASA reports partial lighting recovery around Kyiv in May. This selected regional view does not establish national recovery, a count of returning people or a measure of intact infrastructure.','202205')]:
 a=card(title,text,'lights',KY,6);a['media']=[image(month)];a['sources']=['nasa-ukraine-lights'];s.append(a)
s.append(card('Energy also depends on water','The June 2023 Kakhovka disaster disrupted an interconnected water and energy system. Its location is shown separately from the 2022 light images: the observations describe different dates and different phenomena.','dam',[33,47],6))
story('ua-energy','Energy and night lights','Three dated Kyiv images, with limits on what darkness can tell us.',items,s,['nasa-ukraine-lights'],notes='Imagery source '+NASA+' . January/March/May 2022 display composites are compressed to WebP without georeferencing. Source URLs and SHA256 hashes are in data/history/ukraine/lights.json. They have no calibrated radiance scale; do not infer population, damage or military control. Kakhovka '+DAM+' .')

items=[event('Displacement inside Ukraine',20251231,KY,'UNHCR’s year-end 2025 emergency impact report estimates 3.7 million internally displaced people in Ukraine. Kyiv anchors the national estimate, not a count for the city.',REF,'inside'),event('Two measures of displacement',20251231,KY,'The same emergency report gives 5.9 million refugees worldwide. This operational estimate differs from the 5.224 million in the annual population series used here; definitions, coverage and revisions differ.',REF,'definitions')]
flows=dict(type='flows',data='flows',group='ref',year=2025,top=12,color='muted',vmax=1500000,maxW=10,title='Ukraine-origin refugee stocks',fmt='int')
flows['from']=['UKR']
sc=[dict(title='Across borders',text='The annual UNHCR series counts about 5.22 million Ukraine-origin refugees at the end of 2025. The lines connect origin and asylum countries; they measure stocks, not journeys or border crossings. Only pairs of at least 5,000 people are included.',view=dict(mode='globe',center=[20,51],zoom=3),layers=[flows],sources=['unhcr']),dict(title='Before and after 2022',text='The Ukraine-origin annual series rose sharply in 2022. Line widths retain one scale across years. Its fall in 2024 partly reflects UNHCR stopping the listing of roughly 1.2 million Ukrainians in Russia. It is a coverage break, not proof that those people moved away.',view=dict(mode='globe',center=[25,50],zoom=3),layers=[dict(flows,year='t')],timeline=dict(years=[2021,2022,2023,2024,2025],start=2021),media=[dict(type='line',data='stocks',series='origin',countries=['UKR'],title='Ukraine-origin refugees, annual stocks',fmt='int')],sources=['unhcr']),card('Displaced within the country','Cross-border refugee data leaves out internal displacement. UNHCR’s year-end 2025 emergency report estimates 3.7 million internally displaced people. The national marker does not map their individual destinations.','inside'),card('A stock is not a crossing','A person can cross a border more than once, return temporarily, or be counted under different protection categories. The emergency report’s 5.9 million estimate and the annual series’ 5.22 million total are presented with their own coverage, rather than added or treated as interchangeable.','definitions')]
story('ua-refugees','Refugees and displacement','Separate measures for people abroad and people displaced within Ukraine.',items,sc,['unhcr'],dict(stocks='data/people/refugees.json',flows='data/people/refugees-flows.json'),notes='Annual series: UNHCR Refugee Population Statistics, refugees under its mandate plus other people needing international protection, excluding asylum seekers and IDPs. Annual flow pairs at least 5,000 are stocks, not migration routes. Russia coverage break documented in https://www.unhcr.org/sites/default/files/2025-06/global-trends-report-2024.pdf . Separate operational estimate '+REF+' .')

items=[event('Event coverage ends in August',20260831,KY,'The shipped UCDP record ends in August 2026. Candidate data is preliminary. The 14 October editorial cutoff does not extend its observation window.', 'https://ucdp.uu.se/downloads/','events'),event('Displacement observation window',20251231,KY,'Annual refugee stocks stop at end-2025; the separate operational IDP estimate also refers to year-end 2025. Neither is an October 2026 census.',REF,'people'),event('Image observation window',20220531,KY,'The three NASA Kyiv images stop in May 2022. They illustrate an early-war comparison and cannot be relabelled as a current infrastructure assessment.',NASA,'imagery')]
story('ua-snapshot','Where things stood at the cutoff','An October 2026 editorial cutoff with the observation windows kept visible.',items,[events('Latest included events: August 2026','This scene shows the latest month actually present in the shipped UCDP data. August 2026 Candidate records remain preliminary. There is no claim to locate today’s front or to cover incidents in September and October.',[202606,202607,202608],start=202608),card('Observation dates differ','A release can combine records with different dates. The annual displacement series stops in 2025; it cannot establish the number displaced at the October 2026 editorial cutoff.','people'),card('Early images stay early','The Kyiv light images remain a January-to-May 2022 comparison. Their date is part of their meaning; reusing them as a present-day energy map would hide years of subsequent change.','imagery',KY,6),card('What this snapshot can establish','The latest included event month is August 2026, the annual refugee window ends in 2025, and the imagery comparison ends in May 2022. Sources can be revised. These dated observations document selected aspects of the war, while leaving current control and unobserved events unresolved.','events')],['ucdp-ged','unhcr','nasa-ukraine-lights'],notes='This is a reproducible set of source windows, not a territorial-control update. UCDP '+ 'https://ucdp.uu.se/downloads/'+' ; operational displacement '+REF+' ; imagery '+NASA+' .')
print('Seven Ukraine chapters, 28 scenes, built offline; no territory inference.')





